toc 
disp(max(w)); 
%求得各样本投影值r 
a=e(find(w==max(w)),:); 
for i=1:12 
 r(i)=sum(x(i,:).*a); 
end 
function a=suiji(n) 
 for k=1:n 
 b(k)=rand(); 
 end 
 temp=sum(b.^2); 
 a=sqrt(b.^2/temp); 
end 
function y=Target(x,a) 
 [m,n]=size(x); 
 for i=1:m 
 s1=0; 
 for j=1:n 
 s1=s1+a(j)*x(i,j); 
 end 
 z(i)=s1; 
 end 
 Sz=std(z); 
 R=0.1*Sz; 
 s3=0; 
 for i=1:m 
 for j=1:m 
 r=abs(z(i)-z(j)); 
 t=R-r; 
 if t>=0 
 u=1; 
 else 
 u=0; 
 end 
 s3=s3+t*u; 
 end 
 end 
 Dz=s3; 
 y=Sz*Dz; 
end

